 ]),
 )
 console.log(Cause.failures(cause))
 console.log(Cause.defects(cause))
})

Effect.runPromise(program)
/
Output:
{ id: 'Chunk', values: [ 'error 1' ] }
{ id: 'Chunk', values: [] }
