// ▼
const fib10Fiber = Micro.fork(fib(10))

const program = Micro.gen(function () {
 // Retrieve the fiber
 const fiber = yield fib10Fiber
 // Join the fiber and get the result
 const n = yield Micro.fiberJoin(fiber)
 console.log(n)
})

