 Match.when({ role: "admin" }, () => "Has full access"),
 Match.when({ role: "editor" }, () => "Can edit content"),
 Match.result, // Wrap the result in a Result
)

console.log(getRole({ role: "admin" }))
getRole({ role: "admin" }) // => Result.succeed("Has full access")

