在每次处理都需要精确数量元素的场景中，这个函数很有用：它能确保在该批次凑齐之前，操作不会继续。

示例（取出固定数量的元素）

const program = Effect.gen(function () {
 // Create a queue that can hold up to 100 elements
 const queue = yield Queue.bounded (100)

 // Fork a fiber that attempts to take 3 items from the queue
 const fiber = yield Effect.forkChild(
 Effect.gen(function () {
 console.log("Attempting to take 3 items from the queue...")
 const chunk = yield Queue.takeN(queue, 3)
 console.log(Successfully took 3 items: ${chunk})
 …

要一次性取出队列中的所有元素，请使用 Queue.takeAll。该操作会立即完成：如果队列为空，则返回空集合。

示例（取出所有元素）

const program = Effect.gen(function () {
 const queue = yield Queue.bounded (100)
 // Adds items to the queue
 yield Queue.offer(queue, 10)
 yield Queue.offer(queue, 20)
 yield Queue.offer(queue, 30)
 // Retrieves all items from the queue
 const chunk = yield Queue.takeAll(queue)
 return chunk
})

await Effect.runPromise(program) // => [10, 20, 30]

Queue.shutdown 操作允许你中断当前所有挂起在 offer 或 take 操作上的 Fiber。该操作还会清空队列，并使之后任何 offer 与 take 调用立即终止。

示例（关闭 Queue 时中断 Fiber）

const program = Effect.gen(function () {
 const queue = yield Queue.bounded (3)
 // Forks a fiber that waits to take an item from the queue
 const fiber = yield Effect.forkChild(Queue.take(queue))
 // Shuts down the queue, interrupting the fiber
 yield Queue.shutdown(queue)
 // Joins the interrupted fiber
 yield Fiber.join(fiber)
})

const exit = await Effect.runPromiseExit(program)
exit.tag // => "Failure"

Queue.await 操作会一直等待，直到队列进入 Done 状态。由于 Queue.shutdown 会以一个中断原因（interrupt cause）完成队列，正在等待关闭的 effect 自身也会被中断，而不会作为正常成功来结束。若想无论结果如何都执行清理逻辑，请使用 Effect.onExit 而不是 Effect.andThen，并使用 Fiber.await 而不是 Fiber.join，这样中断就不会传播到执行 join 的 Fiber。

示例（等待 Queue 关闭）

const program = Effect.gen(function () {
 const queue = yield Queue.bounded (3)
 // Forks a fiber to await queue shutdown and log a message,
 // regardless of whether the wait completes or is interrupted
 const fiber = yield Effect.forkChild(
 Queue.await(queue).pipe(Effect.onExit(() => Console.log("shutting down"))),
 )
 // Shuts down the queue, triggering (and interrupting) the await in the fiber
 yield Queue.shutdown …

所有向队列添加值的方法都由 Enqueue 接口定义。这样就把队列限制为只能执行 offer 操作。

示例（把 Queue 限制为只能执行 offer 操作）

const send = (offerOnlyQueue: Queue.Enqueue , value: number) => {
 // This queue is restricted to offer operations only

 // Error: cannot use take on an offer-only queue
 // @errors: 2345
 Queue.take(offerOnlyQueue)

 // Valid offer operation
 return Queue.offer(offerOnlyQueue, value)
}

类似地，所有从队列取出值的方法都由 Dequeue 接口定义，它把队列限制为只能执行 take 操作。

示例（把 Queue 限制为只能执行 take 操作）

const receive = (takeOnlyQueue: Queue.Dequeue ) => {
 // This queue is restricted to take operations only

 // Error: cannot use offer on a take-only queue
 // @errors: 2345
 Queue.offer(takeOnlyQueue, 1)

 // Valid take operation
 return Queue.take(takeOnlyQueue)
}

Queue 类型同时组合了 Enqueue 和 Dequeue，因此你可以轻松地把它传给代码的不同部分，并按需只暴露 Enqueue 或 Dequeue 的行为。

示例（同时使用只 offer 和只 take 的 Queue）

const send = (offerOnlyQueue: Queue.Enqueue , value: number) => {
 return Queue.offer(offerOnlyQueue, value)
}

const receive = (takeOnlyQueue: Queue.Dequeue ) => {
 return Queue.take(takeOnlyQueue)
}

const program = Effect.gen(function () {
 const queue = yield Queue.unbounded ()

 // Add values to the queue
 yield send(queue, 1)
 yield send(queue, 2)

 // Retrieve values from the queue
 const first = yield receive(queue …

Semaphore.make 函数会用指定数量的许可初始化一个 semaphore。

每个许可允许一个任务并发地访问资源或执行操作，而多个许可则可以实现可配置的并发级别。

示例（创建一个带 3 个许可的 Semaphore）

// Create a semaphore with 3 permits
const mutex = Semaphore.make(3)

// The semaphore was created with exactly 3 permits available
const acquired = await Effect.runPromise(
 mutex.pipe(Effect.flatMap((sem) => Semaphore.take(sem, 3))),
)
acquired // => 3

withPermits 方法允许你指定运行某个 effect 所需的许可数量。一旦所需的许可可用，它就会运行该 effect，并在任务完成时自动释放这些许可。

示例（用一个许可的 Semaphore 强制任务串行执行）

在这个示例中，三个任务被并发启动，但它们会串行执行，因为只有一个许可的 semaphore 一次只允许一个任务继续执行。

const task = Effect.gen(function () {
 yield Effect.log("start")
 yield Effect.sleep("2 seconds")
 yield Effect.log("end")
})

const program = Effect.gen(function () {
 const mutex = yield Semaphore.make(1)

 // Wrap the task to require one permit, forcing sequential execution
 const semTask = mutex.withPermits(1)(task).pipe(Effect.withLogSpan("elapsed"))

 // Run 3 tasks concurrently, but they execute sequentially
 // due to the one-perm …

示例（使用多个许可控制并发任务的执行）

在这个示例中，我们创建一个带五个许可的 semaphore，并使用 withPermits(n) 为每个任务分配不同数量的许可：

const program = Effect.gen(function () {
 const mutex = yield Semaphore.make(5)

 const tasks = [1, 2, 3, 4, 5].map((n) =>
 mutex
 .withPermits(n)(Effect.delay(Effect.log(process: ${n}), "2 seconds"))
 .pipe(Effect.withLogSpan("elapsed")),
 )

 yield Effect.all(tasks, { concurrency: "unbounded" })
})

await Effect.runPromise(program) // => undefined
/
Output:
timestamp=... level=INFO fiber=#1 message="process: 1" elapsed=2011ms
t …

对于单个值，使用 Config 模块中的构造器；要把它们组合起来，使用 Config.all。

示例（使用指定 Provider 解析 Config）

const AppConfig = Config.all({
 host: Config.nonEmptyString("HOST"),
 port: Config.port("PORT"),
})

const provider = ConfigProvider.fromEnv({
 env: {
 HOST: "localhost",
 PORT: "8080",
 },
})

const result = Effect.runSync(AppConfig.parse(provider))

result // => { host: "localhost", port: 8080 }

当 provider 已经可以显式拿到时，调用 config.parse(provider) 会很有用，尤其是在测试中。

在应用代码里，Config 也可以改为作为一个 Effect 被 yield。此时它会使用安装在 Effect 上下文中的 ConfigProvider；如果没有显式安装 provider，Effect 会使用 ConfigProvider.fromEnv()。

示例（使用默认的环境 Provider）

const AppConfig = Config.all({
 host: Config.nonEmptyString("HOST"),
 port: Config.port("PORT").pipe(Config.withDefault(8080)),
})

const program = Effect.gen(function () {
 const { host, port } = yield AppConfig
 console.log(Application started: ${host}:${port})
})

Effect.runPromise(program)

HOST=localhost PORT=3000 npx tsx app.ts

Application started: localhost:3000

当某项配置需要自定义类型、校验或结构化表示时，使用 Config.schema。provider 提供编码后的表示，而生成的 Config 会产出该 schema 的 Type。

示例（校验配置值）

const Username = Schema.String.check(
 Schema.isMinLength(4, { message: "Expected at least 4 characters" }),
)

const username = Config.schema(Username, "USERNAME")
const provider = ConfigProvider.fromEnv({ env: { USERNAME: "alice" } })

Effect.runSync(username.parse(provider)) // => "alice"

Schema 也可以描述整个配置对象。

示例（读取结构化配置）

const ServerConfig = Config.schema(
 Schema.Struct({
 host: Schema.String,
 port: Config.Port,
 }),
 "server",
)

const provider = ConfigProvider.fromUnknown({
 server: {
 host: "localhost",
 port: 8080,
 },
})

Effect.runSync(ServerConfig.parse(provider)) // => { host: "localhost", port: 8080 }

Config.schema 会从 schema 推导出一种树状的字符串编码。这样一来，同一份结构化配置既可以通过环境 provider 读取 SERVERHOST 和 SERVERPORT，也可以通过 ConfigProvider.fromUnknown 读取 { server: { host, port } }。

更多细节参见 Schema 的 Config。

Config.Array 和 Config.Record 是用于这类值的 schema：它们既可以按结构化方式提供，也可以作为一个带分隔符的字符串提供。请把它们传给 Config.schema；它们不是 Config 的组合子。

示例（读取逗号分隔的数组）

const exporters = Config.schema(Config.Array(Schema.String), "EXPORTERS")
const provider = ConfigProvider.fromEnv({
 env: { EXPORTERS: "otlp,prometheus" },
})

Effect.runSync(exporters.parse(provider)) // => ["otlp", "prometheus"]

Config.Record(key, value) 类似地既接受一个 record，也接受形如 "service.name=api,service.version=1.0" 的字符串。这两个 schema 都接受用于自定义分隔符的选项。

当 provider 必须提供结构化的数组或对象、而不是一个带分隔符的标量值时，普通的 Schema.Array 和 Schema.Record 依然有用。

Config.all 把多个 config 组合成一个元组或一个具名对象，同时保留输入的形状。

示例（组合并嵌套 Config）

const DatabaseConfig = Config.all({
 host: Config.nonEmptyString("HOST"),
 port: Config.port("PORT"),
}).pipe(Config.nested("DATABASE"))

const provider = ConfigProvider.fromEnv({
 env: {
 DATABASEHOST: "localhost",
 DATABASEPORT: "5432",
 },
})

Effect.runSync(DatabaseConfig.parse(provider)) // => { host: "localhost", port: 5432 }

Config.nested(config, path) 会为该 config 执行的每一次查找都加上一个字符串或路径前缀。在使用 ConfigProvider.fromEnv 时，路径片段之间用 连接。

对于那些既接受已构建好的 Config 、又接受嵌套 config record 的 API，Config.Wrap 和 Config.unwrap 分别提供对应的输入类型与转换。

Config.withDefault 仅在相关输入都不存在时才提供一个值。

示例（提供默认值）

const port = Config.port("PORT").pipe(Config.withDefault(8080))
const provider = ConfigProvider.fromUnknown({})

Effect.runSync(port.parse(provider)) // => 8080

无效输入不会被当作缺失处理。例如 PORT=not-a-port 仍然会失败，而不会悄悄产出 8080。组合 config 也遵循同样的规则：如果组中的一部分已提供，那么缺失或无效的兄弟项会让这个组不完整，而不是用默认值替换整个组。

如果希望缺失时产出 Option，请使用 Config.option。

示例（读取可选值）

const apiKey = Config.string("APIKEY").pipe(Config.option)
const provider = ConfigProvider.fromUnknown({})

Effect.runSync(apiKey.parse(provider)) // => Option.none()

Config.orElse 比 Config.withDefault 适用范围更广：它在出现任何 ConfigError（包括无效输入）之后都会尝试另一个 config。

示例（fallback 到另一个 Config）

const host = Config.string("HOST").pipe(
 Config.orElse(() => Config.string("FALLBACKHOST")),
)

const provider = ConfigProvider.fromUnknown({ FALLBACKHOST: "localhost" })

Effect.runSync(host.parse(provider)) // => "localhost"

由于 orElse 可以从校验错误中恢复，只有在你确实有意替换无效输入时才使用它。对于「只有缺失才触发 fallback」这种常见情形，请使用 withDefault。

对于不会失败的转换，使用 Config.map。

示例（映射 Config）

const origin = Config.all({
 host: Config.nonEmptyString("HOST"),
 port: Config.port("PORT"),
}).pipe(Config.map(({ host, port }) => http://${host}:${port}))

const provider = ConfigProvider.fromUnknown({
 HOST: "localhost",
 PORT: 8080,
})

Effect.runSync(origin.parse(provider)) // => "http://localhost:8080"

对于校验和解析，优先把规则表达在 schema 中并使用 Config.schema。如果某个转换需要改为返回 Effect ，可以使用 Config.mapOrFail。

Config.redacted 会把字符串包装成 Redacted ，其字符串表示不会暴露该值。要访问这个秘密，必须显式调用 Redacted.value。

示例（保护机密值）

const apiKey = Config.redacted("APIKEY")
const provider = ConfigProvider.fromEnv({
 env: { APIKEY: "secret-value" },
})

const result = Effect.runSync(apiKey.parse(provider))

String(result) // => " "
Redacted.value(result) // => "secret-value"

如果需要先解码某个值、再把它包装起来，可以把 Config.schema 与 Schema.RedactedFromValue 结合使用。

const secretNumber = Config.schema(
 Schema.RedactedFromValue(Schema.FiniteFromString),
 "SECRETNUMBER",
)

const provider = ConfigProvider.fromEnv({
 env: { SECRETNUMBER: "42" },
})

const result = Effect.runSync(secretNumber.parse(provider))

Redacted.value(result) // => 42

对于 JavaScript 值或解析后的 JSON 对象，使用 ConfigProvider.fromUnknown。对象的键和数组索引会成为配置路径片段。

示例（加载解析后的 JSON 对象）

const provider = ConfigProvider.fromUnknown(
 JSON.parse({"server":{"host":"localhost","port":8080}}),
)

const server = Config.all({
 host: Config.string("host"),
 port: Config.port("port"),
}).pipe(Config.nested("server"))

Effect.runSync(server.parse(provider)) // => { host: "localhost", port: 8080 }

Provider 组合子会改变所有 config 查找其路径的方式：
ConfigProvider.nested 为每一次查找加上前缀。
ConfigProvider.constantCase 把字符串路径片段转换为 CONSTANTCASE。
ConfigProvider.mapInput 执行任意的路径转换。

示例（把 camelCase 键适配为环境变量）

const provider = ConfigProvider.fromEnv({
 env: { DATABASEHOST: "localhost" },
}).pipe(ConfigProvider.constantCase)

const databaseHost = Config.string("databaseHost")

Effect.runSync(databaseHost.parse(provider)) // => "localhost"

ConfigProvider.orElse(primary, fallback) 仅在 primary provider 于所请求路径上没有值时才查询 fallback。与 Config.orElse 不同，它不会从来源错误或 schema 校验错误中恢复。

示例（为 Provider 添加默认值）

const environment = ConfigProvider.fromEnv({
 env: { HOST: "production.example.com" },
})

const defaults = ConfigProvider.fromUnknown({
 HOST: "localhost",
 PORT: 8080,
})

const provider = ConfigProvider.orElse(environment, defaults)
const app = Config.all({
 host: Config.string("HOST"),
 port: Config.port("PORT"),
})

Effect.runSync(app.parse(provider)) // => { host: "production.example.com", port: 8080 }

使用 ConfigProvider.layer(provider) 可以替换那些作为 Effect 被 yield 的 config 所使用的 provider。ConfigProvider.layerAdd(provider) 则是为当前 provider 添加一个 fallback；传入 { asPrimary: true } 可以让新增的 provider 优先。

示例（提供 ConfigProvider Layer）

const provider = ConfigProvider.fromUnknown({ PORT: 8080 })
const ProviderLayer = ConfigProvider.layer(provider)

const program = Effect.gen(function () {
 return yield Config.port("PORT")
})

Effect.runSync(Effect.provide(program, ProviderLayer)) // => 8080

对于单个 config，config.parse(provider) 更简单，而且不会改变 Effect 程序中其余部分所使用的 provider。

make 函数通过指定一个 BigInt 数值和一个 scale 来创建 BigDecimal。scale 决定小数点右侧的位数。

示例（使用指定的 scale 创建 BigDecimal）

// Create a BigDecimal from a BigInt (1n) with a scale of 2
const decimal = BigDecimal.make(1n, 2)

console.log(decimal)
decimal // => BigDecimal.make(1n, 2)

// Convert the BigDecimal to a string
console.log(String(decimal))
String(decimal) // => "BigDecimal(0.01)"

// Format the BigDecimal as a standard decimal string
console.log(BigDecimal.format(decimal))
BigDecimal.format(decimal) // => "0.01"

// Convert the BigDecimal to exponential notation
console.lo …

若要检查两个 BigDecimal 值在数值上是否相等（无论其内部表示如何），请使用 BigDecimal.equals 函数。

示例（检查相等性）

const dec1 = BigDecimal.make(105n, 2)
const dec2 = BigDecimal.make(1050n, 3)

console.log(BigDecimal.equals(dec1, dec2))
BigDecimal.equals(dec1, dec2) // => true

你可以使用 Effect.failCause 有意创建一个带有特定 cause 的 effect。

示例（定义带有不同 Cause 的 Effect）

// Define an effect that dies with an unexpected error
//
// ┌─── Effect 
// ▼
const die = Effect.failCause(Cause.die("Boom!"))

// Define an effect that fails with an expected error
//
// ┌─── Effect 
// ▼
const fail = Effect.failCause(Cause.fail("Oh no!"))

Effect.runSyncExit(fail) // => Exit.fail("Oh no!")

有些 cause 不会影响 effect 的错误类型，因此错误通道中会是 never：

┌─── no error information
 ▼
Effect 

例如，Cause.die 不会为 effect 指定错误类型，而 Cause.fail 会，并据此设置错误通道的类型。

要获取一个失败 effect 的 cause，请使用 Effect.exit 并检查 Failure 的 cause 字段。这让你可以检查或处理失败背后的确切原因。

示例（获取并检查失败的 Cause）

const program = Effect.gen(function () {
 const exit = yield Effect.exit(Effect.fail("Oh no!"))
 if (Exit.isFailure(exit)) {
 console.log(exit.cause)
 exit.cause // => Cause.fail("Oh no!")
 }
})

await Effect.runPromise(program)

若要根据具体的错误场景做出自定义响应，可以遍历 cause.reasons 并对每个原因的 tag 做 switch。

示例（格式化 Cause 中的每个原因）

const cause = Cause.combine(
 Cause.fail(new Error("my fail message")),
 Cause.die("my die message"),
)

const formatted = cause.reasons
 .map((reason) => {
 switch (reason.tag) {
 case "Fail":
 return (error: ${reason.error.message})
 case "Die":
 return (defect: ${reason.defect})
 case "Interrupt":
 return (fiberId: ${reason.fiberId})
 }
 })
 .join(", ")

formatted // => "(error: my fail message), (defect: my …

用 Cause.isFailReason 和 Cause.isDieReason 过滤 cause.reasons，就能只检查发生的预期错误或非预期 defect。

示例（从 Cause 中提取失败与 Defect）

const program = Effect.gen(function () {
 const exit = yield Effect.exit(
 Effect.all([
 Effect.fail("error 1"),
 Effect.die("defect"),
 Effect.fail("error 2"),
 ]),
 )
 if (Exit.isFailure(exit)) {
 console.log(
 exit.cause.reasons
 .filter(Cause.isFailReason)
 .map((reason) => reason.error),
 )
 exit.cause.reasons.filter(Cause.isFailReason).map((reason) => reason.error) // => ["error 1"]
 cons …

使用 Chunk.empty 创建一个空的 Chunk。

示例（创建一个空 Chunk）

// ┌─── Chunk 
// ▼
const chunk = Chunk.empty ()

Chunk.toReadonlyArray(chunk) // => []

要创建包含特定值的 Chunk，请使用 Chunk.make(...values)。注意，得到的 chunk 在类型上被标记为非空。

示例（创建一个非空 Chunk）

// ┌─── NonEmptyChunk 
// ▼
const chunk = Chunk.make(1, 2, 3)

Chunk.toReadonlyArray(chunk) // => [1, 2, 3]

要将两个 Chunk 实例合并为一个，请使用 Chunk.appendAll。

示例（将两个 Chunk 合并为一个）

// Concatenate two chunks with different types of elements
//
// ┌─── NonEmptyChunk 
// ▼
const chunk = Chunk.appendAll(Chunk.make(1, 2), Chunk.make("a", "b"))

console.log(chunk)
/
Output:
{ id: 'Chunk', values: [ 1, 2, 'a', 'b' ] }
/
Chunk.toReadonlyArray(chunk) // => [1, 2, "a", "b"]

要从 Chunk 的开头移除元素，请使用 Chunk.drop，并指定要丢弃的元素数量。

示例（从开头丢弃元素）

// Drops the first 2 elements from the Chunk
const chunk = Chunk.drop(Chunk.make(1, 2, 3, 4), 2)

Chunk.toReadonlyArray(chunk) // => [3, 4]

使用 Chunk.toReadonlyArray 可以把 Chunk 转换为 ReadonlyArray。得到的类型会随 Chunk 内容的不同而变化，用以区分空 chunk、非空 chunk 以及一般 chunk。

示例（将 Chunk 转换为 ReadonlyArray）

// ┌─── readonly [number, ...number[]]
// ▼
const nonEmptyArray = Chunk.toReadonlyArray(Chunk.make(1, 2, 3))

// ┌─── readonly never[]
// ▼
const emptyArray = Chunk.toReadonlyArray(Chunk.empty())

declare const chunk: Chunk.Chunk 

// ┌─── readonly number[]
// ▼
const array = Chunk.toReadonlyArray(chunk)

