let attempts = 0
const request = Effect.suspend(() => {
 attempts++
 return attempts < 2 ? Effect.fail("temporary") : Effect.succeed("ok")
})

const program = request.pipe(Effect.retry(Schedule.recurs(3)))

Effect.runSync(program) // => "ok"

当重复取决于成功的值而不是错误时，请改用 Effect.repeat。

Effect.sandbox 会把完整的失败 Cause 暴露在类型化错误通道中：

Effect -> Effect , R>

与普通的类型化错误不同，一个 Cause 可以包含类型化失败、defect、中断，或者同时包含多种原因。Cause 是扁平的：检查只读的 reasons 数组，并使用 Cause 模块提供的 reason 守卫。

示例（检查沙箱化后的 Cause）

const sandboxed = Effect.fail("invalid input").pipe(Effect.sandbox)

const program = sandboxed.pipe(
 Effect.catch((cause) => {
 const failure = cause.reasons.find(Cause.isFailReason)
 return failure === undefined
 ? Effect.fail(cause)
 : Effect.succeed(Recovered from: ${failure.error})
 }),
)

Effect.runSync(program) // => "Recovered from: invalid input"

当一个沙箱化的 effect 没有以其他方式恢复时，可以用 Effect.catch(Effect.failCause) 把它的错误通道转换回原来的失败模型：

const sandboxed = Effect.fail("invalid input").pipe(Effect.sandbox)
const restored = sandboxed.pipe(Effect.catch(Effect.failCause))

Effect.runSyncExit(restored) // => Exit.fail("invalid input")

对于单步恢复，Effect.catchCause 通常更简单，因为它直接提供相同的 Cause，而无需先改变错误类型。

Effect.timeout 会把超时表示为一个类型化的 Cause.TimeoutError。

示例（以 TimeoutError 失败）

const program = Effect.never.pipe(Effect.timeout(0))
const error = await Effect.runPromise(Effect.flip(program))

error.tag // => "TimeoutError"

如果源在超时之前就失败了，它原本的错误会被保留。如果它及时成功，它的成功值会原样返回。

const program = Effect.succeed("result").pipe(Effect.timeout("1 second"))

Effect.runSync(program) // => "result"

Effect.timeoutOption 只把超时这一种情况表示为 Option.none()。及时的成功会变成 Option.some(value)，而来自源的类型化失败仍然留在错误通道里。

示例（超时时返回 None）

const timedOut = await Effect.runPromise(
 Effect.never.pipe(Effect.timeoutOption(0)),
)

timedOut // => Option.none()

const completed = Effect.runSync(
 Effect.succeed("result").pipe(Effect.timeoutOption("1 second")),
)

completed // => Option.some("result")

只有当超时确实意味着「不存在」时，才使用这个操作符。它不会丢弃源 Effect 中普通的失败。

当超时胜出时，Effect.timeoutOrElse 会切换到一个惰性构造的 fallback Effect。这个 fallback 可以引入它自己的成功、错误与依赖类型。

示例（超时时使用缓存数据）

const program = Effect.never.pipe(
 Effect.timeoutOrElse({
 duration: 0,
 orElse: () => Effect.succeed("cached result"),
 }),
)

await Effect.runPromise(program) // => "cached result"

当超时应当使用领域特有的错误时，从 fallback 中返回 Effect.fail。

class RequestTimeout extends Data.TaggedError("RequestTimeout")<{
 readonly endpoint: string
}> {}

const program = Effect.never.pipe(
 Effect.timeoutOrElse({
 duration: 0,
 orElse: () => Effect.fail(new RequestTimeout({ endpoint: "/users" })),
 }),
)

await Effect.runPromiseExit(program) // => Exit.fail(new RequestTimeout({ endpoint: "/users" }))

改为从 fallback 中返回 Effect.die 或 Effect.failCause(Cause.die(...))，就会把这次超时变成一个 defect。这应当只保留给「超时意味着破坏了某个不变式」的场景。

Effect.orDie 会把每个类型化失败转换为 defect，并移除类型化错误通道。

示例（把一次失败当作不可恢复）

const program = Effect.fail(new Error("Invalid startup configuration")).pipe(
 Effect.orDie,
)

const exit = Effect.runSyncExit(program)

Exit.isFailure(exit) && exit.cause.reasons[0]?.tag // => "Die"

要自定义 defect，请先用 Effect.mapError 转换类型化错误，再套用 Effect.orDie。

const program = Effect.fail("missing token").pipe(
 Effect.mapError((message) => new Error(Startup failed: ${message})),
 Effect.orDie,
)

const exit = Effect.runSyncExit(program)

const reason = Exit.isFailure(exit) ? exit.cause.reasons[0] : undefined
const message =
 reason !== undefined &&
 Cause.isDieReason(reason) &&
 Predicate.isError(reason.defect)
 ? reason.defect.message
 : undefined

message // => "Startup failed: mi …

Effect.catchDefect 只处理 defect。类型化失败与中断保持原样。

示例（从 defect 中恢复）

const program = Effect.die(new Error("plugin crashed")).pipe(
 Effect.catchDefect((defect) =>
 Predicate.isError(defect)
 ? Effect.succeed(disabled plugin: ${defect.message})
 : Effect.die(defect),
 ),
)

Effect.runSync(program) // => "disabled plugin: plugin crashed"

